CREATE OR REPLACE FUNCTION public."captureVideoOperationalEvent"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
  DECLARE mapped_type TEXT; source_id TEXT; terminal_pos TEXT; event_time TIMESTAMPTZ; actor_id TEXT; actor_name TEXT; event_amount NUMERIC(14,2); offset_seconds INTEGER; retention_days INTEGER;
  BEGIN
    IF TG_TABLE_NAME='StoreTransaction' THEN
      IF TG_OP='UPDATE' AND OLD."reversedAt" IS NULL AND NEW."reversedAt" IS NOT NULL THEN mapped_type:='REVERSAL';
      ELSIF TG_OP='INSERT' AND NEW."type"='SUPPLIER_PAYMENT' THEN mapped_type:='SUPPLIER_PAYMENT';
      ELSIF TG_OP='INSERT' AND NEW."type"='PERCENTAGES' THEN mapped_type:='SUSPICIOUS_ACTION'; ELSE RETURN NEW; END IF;
      source_id:=NEW."id";event_time:=COALESCE(NEW."reversedAt",NEW."occurredAt",NOW());actor_id:=COALESCE(NEW."reversedBy",NEW."actorId");actor_name:=COALESCE(NEW."reversedByName",NEW."actorName");event_amount:=NEW."amount";
      SELECT COALESCE(s."terminalPos",'MAIN') INTO terminal_pos FROM "CashShiftSession" s WHERE s."id"=NEW."sessionId";terminal_pos:=COALESCE(terminal_pos,'BACKOFFICE');
    ELSIF TG_TABLE_NAME='PosSaleActionAudit' THEN
      mapped_type:=CASE WHEN NEW."actionType" IN ('CANCEL','POS_CANCEL') THEN 'VOID' WHEN NEW."actionType" IN ('RETURN','RETURN_ITEMS') THEN 'RETURN' WHEN NEW."actionType" IN ('DISCOUNT','PRICE_CHANGE') THEN 'DISCOUNT' WHEN NEW."actionType" IN ('DRAWER_OPEN','SHIFT_OPEN') THEN 'DRAWER_OPEN' WHEN NEW."actionType" IN ('DUPLICATE_BLOCKED','DUPLICATE_CONFIRMED','UNKNOWN_PRODUCT_SCAN','SUSPICIOUS_ACTION') THEN 'SUSPICIOUS_ACTION' ELSE NULL END;
      IF mapped_type IS NULL THEN RETURN NEW; END IF;source_id:=NEW."id";event_time:=NEW."createdAt";actor_id:=NEW."actorId";actor_name:=NEW."actorName";event_amount:=NULL;terminal_pos:=COALESCE(NEW."details"->>'terminalPos','MAIN');
    ELSIF TG_TABLE_NAME='CashShiftSession' THEN
      IF TG_OP='INSERT' AND ABS(COALESCE(NEW."openingVariance",0))>0.009 THEN mapped_type:='CASH_DIFFERENCE';event_amount:=NEW."openingVariance";actor_id:=NEW."openedBy";actor_name:=NEW."openedByName";event_time:=NEW."openedAt";
      ELSIF TG_OP='UPDATE' AND OLD."status"='OPEN' AND NEW."status"='CLOSED' AND ABS(COALESCE(NEW."variance",0))>0.009 THEN mapped_type:='CASH_DIFFERENCE';event_amount:=NEW."variance";actor_id:=NEW."closedBy";actor_name:=NEW."closedByName";event_time:=NEW."closedAt"; ELSE RETURN NEW; END IF;
      source_id:=NEW."id";terminal_pos:=COALESCE(NEW."terminalPos",'MAIN');
    ELSE RETURN NEW; END IF;
    IF NOT EXISTS (SELECT 1 FROM "CompanyModule" m WHERE m."companyId"=NEW."companyId" AND m."moduleKey"='VIDEO_EVENTS' AND m."active"=TRUE) THEN RETURN NEW; END IF;
    SELECT c."timeOffsetSeconds",c."retentionDays" INTO offset_seconds,retention_days FROM "StoreVideoConnection" c WHERE c."companyId"=NEW."companyId" AND c."storeId"=NEW."storeId" AND c."active"=TRUE LIMIT 1;IF NOT FOUND THEN RETURN NEW;END IF;offset_seconds:=COALESCE(offset_seconds,0);retention_days:=COALESCE(retention_days,30);
    INSERT INTO "VideoOperationalEvent" ("id","companyId","storeId","terminalPos","operatorId","operatorName","eventType","eventAt","nvrEventAt","timeOffsetSeconds","clipStartAt","clipEndAt","sourceType","sourceId","amount","details","expiresAt")
    VALUES (md5(random()::text||clock_timestamp()::text),NEW."companyId",NEW."storeId",terminal_pos,actor_id,actor_name,mapped_type,event_time,event_time+(offset_seconds||' seconds')::interval,offset_seconds,event_time+(offset_seconds||' seconds')::interval-INTERVAL '30 seconds',event_time+(offset_seconds||' seconds')::interval+INTERVAL '60 seconds',TG_TABLE_NAME,source_id,event_amount,jsonb_build_object('capturedAutomatically',true),event_time+(retention_days||' days')::interval) ON CONFLICT DO NOTHING;RETURN NEW;
  END;$function$
CREATE OR REPLACE FUNCTION public.mws_adjust_live_stocktake_expected()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE adjustment RECORD;
BEGIN
  FOR adjustment IN
    SELECT sl."id" AS "lineId",sl."stocktakeId",sl."expectedQuantity"
    FROM "StocktakeLine" sl
    JOIN "Stocktake" st ON st."id"=sl."stocktakeId"
    WHERE st."storeId"=NEW."storeId" AND st."status"='DRAFT' AND st."liveDuringTrading"=TRUE AND sl."productId"=NEW."productId"
  LOOP
    UPDATE "StocktakeLine" SET "expectedQuantity"="expectedQuantity"+NEW."quantity","updatedAt"=NOW() WHERE "id"=adjustment."lineId";
    INSERT INTO "StocktakeMovementAdjustment" ("id","stocktakeId","lineId","movementId","quantity","expectedBefore","expectedAfter","movementType")
    VALUES (md5(random()::text||clock_timestamp()::text),adjustment."stocktakeId",adjustment."lineId",NEW."id",NEW."quantity",adjustment."expectedQuantity",adjustment."expectedQuantity"+NEW."quantity",NEW."movementType")
    ON CONFLICT ("stocktakeId","movementId") DO NOTHING;
  END LOOP;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.mws_consume_preparation_stock_from_pos_audit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
 DECLARE
   sale_id TEXT;
   sale_item JSONB;
   batch_id TEXT;
   batch_row RECORD;
   prep_item JSONB;
   recipe_row RECORD;
   modifier_json JSONB;
   modifier_row RECORD;
   product_qty NUMERIC;
   consume_qty NUMERIC;
   mismatch BOOLEAN;
   milk_modifier_id TEXT;
   milk_target_ingredient_id TEXT;
   milk_target_sku TEXT;
   source_product_sku TEXT;
   milk_qty NUMERIC;
   milk_target_unit TEXT;
   milk_fallback_qty NUMERIC;
   milk_base_qty NUMERIC;
   ice_modifier_id TEXT;
   ice_target_ingredient_id TEXT;
   ice_base_qty NUMERIC;
   ice_target_qty NUMERIC;
   ice_description TEXT;
   decaf_modifier_id TEXT;
   decaf_ingredient_id TEXT;
   coffee_base_qty NUMERIC;
   coffee_base_ingredient_id TEXT;
   extra_modifier_id TEXT;
 BEGIN
   IF NEW."eventType" <> 'POS_SALE_COMPLETED' THEN RETURN NEW; END IF;
   sale_id := COALESCE(NEW."details"->>'saleId','');
   IF sale_id = '' THEN RETURN NEW; END IF;

   FOR sale_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW."details"->'items','[]'::jsonb)) LOOP
     IF COALESCE(sale_item->>'overrideReason','') LIKE 'PREPARATION:%' THEN
       batch_id := split_part(sale_item->>'overrideReason',':',2);
       IF batch_id = '' THEN CONTINUE; END IF;

       SELECT * INTO batch_row FROM "StorePreparationBatch"
       WHERE "id"=batch_id AND "companyId"=NEW."companyId" AND "storeId"=NEW."storeId" AND ("status"='SENT' OR "status"='READY')
       FOR UPDATE;
       IF NOT FOUND THEN CONTINUE; END IF;

       SELECT EXISTS(
         SELECT 1 FROM (
           SELECT x->>'productId' AS product_id,SUM(GREATEST(0,COALESCE((x->>'quantity')::numeric,0))) AS qty
           FROM jsonb_array_elements(COALESCE(batch_row."itemsJson",'[]'::jsonb)) x GROUP BY x->>'productId'
         ) b
         FULL OUTER JOIN (
           SELECT x->>'productId' AS product_id,SUM(GREATEST(0,COALESCE((x->>'quantity')::numeric,0))) AS qty
           FROM jsonb_array_elements(COALESCE(NEW."details"->'items','[]'::jsonb)) x
           WHERE COALESCE(x->>'overrideReason','')='PREPARATION:'||batch_id GROUP BY x->>'productId'
         ) s USING(product_id)
         WHERE b.product_id IS NULL OR s.product_id IS NULL OR b.qty IS DISTINCT FROM s.qty
       ) INTO mismatch;
       IF mismatch THEN RAISE EXCEPTION 'Η παραγγελία παρασκευής δεν συμφωνεί με τα προϊόντα/ποσότητες της πώλησης.' USING ERRCODE='P0001'; END IF;

       FOR prep_item IN SELECT value FROM jsonb_array_elements(COALESCE(batch_row."itemsJson",'[]'::jsonb)) LOOP
         product_qty := GREATEST(0,COALESCE((prep_item->>'quantity')::numeric,0));
         IF product_qty <= 0 THEN CONTINUE; END IF;

         source_product_sku:=NULL;milk_qty:=0;
         SELECT p."sku" INTO source_product_sku FROM "Product" p WHERE p."id"=prep_item->>'productId' AND p."companyId"=NEW."companyId" LIMIT 1;
         milk_qty:=CASE
           WHEN source_product_sku='MWS-KAT-BEV-FREDDO-CAP-LATTE' THEN 140
           WHEN source_product_sku IN ('MWS-KAT-BEV-FREDDO-CAP','MWS-KAT-BEV-DECAF-FREDDO-CAP') THEN 70
           WHEN source_product_sku='MWS-KAT-BEV-ICED-LATTE' THEN 160
           WHEN source_product_sku='MWS-KAT-BEV-FRAPPE-MILK' THEN 30
           WHEN source_product_sku='MWS-KAT-BEV-MOCHA-COLD' THEN 160
           WHEN source_product_sku='MWS-KAT-BEV-MACCHIATO-DOUBLE' THEN 25
           WHEN source_product_sku='MWS-KAT-BEV-MACCHIATO' THEN 17.5
           WHEN source_product_sku='MWS-KAT-BEV-CAP-LATTE-DOUBLE' THEN 180
           WHEN source_product_sku='MWS-KAT-BEV-CAP-LATTE-SINGLE' THEN 170
           WHEN source_product_sku='MWS-KAT-BEV-CAP-DOUBLE' THEN 120
           WHEN source_product_sku IN ('MWS-KAT-BEV-CAP-SINGLE','MWS-KAT-BEV-DECAF-CAP') THEN 100
           WHEN source_product_sku='MWS-KAT-BEV-FLAT-WHITE' THEN 120
           WHEN source_product_sku='MWS-KAT-BEV-CORTADO' THEN 60
           WHEN source_product_sku='MWS-KAT-BEV-MOCHA-HOT' THEN 160
           WHEN source_product_sku IN ('MWS-KAT-BEV-LATTE-HOT','MWS-KAT-BEV-DECAF-LATTE') THEN 180
           WHEN source_product_sku IN ('MWS-KAT-BEV-CHOC-HOT','MWS-KAT-BEV-CHOC-WHITE-HOT','MWS-KAT-BEV-CHOC-HAZ-HOT','MWS-KAT-BEV-CHOC-CARAMEL-HOT') THEN 200
           WHEN source_product_sku IN ('MWS-KAT-BEV-CHOC-COLD','MWS-KAT-BEV-CHOC-WHITE-COLD','MWS-KAT-BEV-CHOC-HAZ-COLD','MWS-KAT-BEV-CHOC-CARAMEL-COLD') THEN 220
           WHEN source_product_sku='MWS-KAT-BEV-MATCHA-HOT' THEN 200
           WHEN source_product_sku='MWS-KAT-BEV-MATCHA-COLD' THEN 220
           ELSE 0 END;

         milk_modifier_id:=NULL;milk_target_ingredient_id:=NULL;milk_target_sku:=NULL;milk_target_unit:='ML';milk_fallback_qty:=NULL;milk_base_qty:=0;
         SELECT m."id",CASE UPPER(TRIM(m."description"))
           WHEN 'ΦΡΕΣΚΟ' THEN 'MWS-PREP-MILK' WHEN 'ΦΡΕΣΚΟ ΓΑΛΑ' THEN 'MWS-PREP-MILK' WHEN 'ΓΑΛΑ ΦΡΕΣΚΟ' THEN 'MWS-PREP-MILK'
           WHEN 'ΓΑΛΑ ΕΒΑΠΟΡΕ' THEN 'MWS-PREP-MILK-EVAP' WHEN 'ΧΩΡΙΣ ΛΑΚΤΟΖΗ' THEN 'MWS-PREP-MILK-LF'
           WHEN 'ΓΑΛΑ ΑΜΥΓΔΑΛΟΥ' THEN 'MWS-PREP-ALMOND' WHEN 'ΓΑΛΑ ΒΡΩΜΗΣ' THEN 'MWS-PREP-OAT' WHEN 'ΓΑΛΑ ΣΟΓΙΑΣ' THEN 'MWS-PREP-SOY' END
         INTO milk_modifier_id,milk_target_sku
         FROM jsonb_array_elements(COALESCE(prep_item->'modifiers','[]'::jsonb)) j
         JOIN "ManagementModifier" m ON m."id"=j->>'id' AND m."companyId"=NEW."companyId" AND m."active"=TRUE
         JOIN "ManagementModifierGroup" g ON g."id"=m."groupId" AND g."companyId"=m."companyId" AND g."active"=TRUE
         WHERE UPPER(g."description")='ΓΑΛΑ' LIMIT 1;

         ice_modifier_id:=NULL;ice_description:=NULL;ice_target_qty:=NULL;ice_base_qty:=0;ice_target_ingredient_id:=NULL;
         SELECT UPPER(j->>'description') INTO ice_description FROM jsonb_array_elements(COALESCE(prep_item->'modifiers','[]'::jsonb)) j
         WHERE COALESCE(j->>'id','') LIKE 'synthetic-ΠΑΓΟΣ ΠΟΣΟΤΗΤΑ-%' LIMIT 1;
         IF ice_description IS NULL THEN
           SELECT m."id",UPPER(m."description") INTO ice_modifier_id,ice_description
           FROM jsonb_array_elements(COALESCE(prep_item->'modifiers','[]'::jsonb)) j
           JOIN "ManagementModifier" m ON m."id"=j->>'id' AND m."companyId"=NEW."companyId" AND m."active"=TRUE
           JOIN "ManagementModifierGroup" g ON g."id"=m."groupId" AND g."companyId"=m."companyId" AND g."active"=TRUE
           WHERE UPPER(g."description")='ΠΑΓΟΣ' LIMIT 1;
         END IF;
         IF ice_description LIKE '%ΧΩΡΙΣ ΠΑΓΟ%' OR ice_description LIKE '%ΠΟΣΟΤΗΤΑ 0%' THEN ice_target_qty:=0;
         ELSIF ice_description LIKE '%ΛΙΓΟΣ ΠΑΓΟΣ%' OR ice_description LIKE '%ΠΟΣΟΤΗΤΑ 1%' THEN ice_target_qty:=50;
         ELSIF ice_description LIKE '%ΚΑΝΟΝΙΚΟΣ ΠΑΓΟΣ%' OR ice_description LIKE '%ΠΟΣΟΤΗΤΑ 2%' THEN ice_target_qty:=100;
         ELSIF ice_description LIKE '%ΠΟΛΥΣ ΠΑΓΟΣ%' OR ice_description LIKE '%ΠΟΣΟΤΗΤΑ 3%' THEN ice_target_qty:=150; END IF;

         decaf_modifier_id:=NULL;decaf_ingredient_id:=NULL;coffee_base_qty:=0;coffee_base_ingredient_id:=NULL;extra_modifier_id:=NULL;
         SELECT m."id" INTO decaf_modifier_id FROM jsonb_array_elements(COALESCE(prep_item->'modifiers','[]'::jsonb)) j JOIN "ManagementModifier" m ON m."id"=j->>'id' AND m."companyId"=NEW."companyId" AND m."active"=TRUE WHERE UPPER(m."description")='DECAF' LIMIT 1;
         SELECT m."id" INTO extra_modifier_id FROM jsonb_array_elements(COALESCE(prep_item->'modifiers','[]'::jsonb)) j JOIN "ManagementModifier" m ON m."id"=j->>'id' AND m."companyId"=NEW."companyId" AND m."active"=TRUE JOIN "ManagementModifierGroup" g ON g."id"=m."groupId" AND g."companyId"=m."companyId" WHERE UPPER(g."description")='EXTRA' AND UPPER(m."description")='EXTRA ΔΟΣΗ' LIMIT 1;
         SELECT p."id" INTO decaf_ingredient_id FROM "Product" p WHERE p."companyId"=NEW."companyId" AND p."sku"='MWS-PREP-DECAF' AND p."active"=TRUE LIMIT 1;

         FOR recipe_row IN
           SELECT r."ingredientProductId",r."quantity",r."unit",p."sku" AS ingredient_sku
           FROM "PreparationRecipeLine" r JOIN "Product" p ON p."id"=r."ingredientProductId" AND p."companyId"=r."companyId"
           WHERE r."companyId"=NEW."companyId" AND r."productId"=prep_item->>'productId' AND r."automatic"=TRUE AND NOT EXISTS(SELECT 1 FROM "StoreBakingPolicy" bp WHERE bp."companyId"=NEW."companyId" AND bp."storeId"=NEW."storeId" AND bp."productId"=r."productId" AND bp."mode"='BAKED') AND NOT EXISTS(SELECT 1 FROM "StoreBakedBalance" bs WHERE bs."companyId"=NEW."companyId" AND bs."storeId"=NEW."storeId" AND bs."productId"=r."productId" AND bs."enabled"=TRUE)
         LOOP
           IF milk_modifier_id IS NOT NULL AND recipe_row.ingredient_sku LIKE 'MWS-PREP-MILK%' THEN milk_base_qty:=milk_base_qty+recipe_row."quantity";CONTINUE; END IF;
           IF ice_target_qty IS NOT NULL AND recipe_row.ingredient_sku='MWS-PREP-ICE' THEN ice_base_qty:=ice_base_qty+recipe_row."quantity";ice_target_ingredient_id:=recipe_row."ingredientProductId";CONTINUE; END IF;
           IF recipe_row.ingredient_sku IN ('MWS-PREP-COFFEE-BEANS','MWS-PREP-DECAF') THEN
             coffee_base_qty:=coffee_base_qty+recipe_row."quantity";
             IF recipe_row.ingredient_sku='MWS-PREP-DECAF' OR decaf_modifier_id IS NOT NULL THEN coffee_base_ingredient_id:=decaf_ingredient_id; ELSE coffee_base_ingredient_id:=recipe_row."ingredientProductId"; END IF;
             CONTINUE;
           END IF;
           consume_qty := product_qty * recipe_row."quantity";
           UPDATE "StoreProduct" sp SET "currentStock"=COALESCE(sp."currentStock",0)-consume_qty FROM "Product" p
           WHERE sp."storeId"=NEW."storeId" AND sp."productId"=recipe_row."ingredientProductId" AND sp."active"=TRUE AND p."id"=sp."productId" AND p."companyId"=NEW."companyId" AND p."trackStock"=TRUE;
           INSERT INTO "PreparationStockConsumption" ("id","companyId","storeId","saleId","batchId","sourceProductId","ingredientProductId","modifierId","quantity","unit","kind") VALUES (gen_random_uuid()::text,NEW."companyId",NEW."storeId",sale_id,batch_id,prep_item->>'productId',recipe_row."ingredientProductId",NULL,consume_qty,recipe_row."unit",'RECIPE') ON CONFLICT DO NOTHING;
         END LOOP;

         IF coffee_base_qty>0 AND coffee_base_ingredient_id IS NOT NULL THEN
           consume_qty:=product_qty*coffee_base_qty;
           UPDATE "StoreProduct" sp SET "currentStock"=COALESCE(sp."currentStock",0)-consume_qty FROM "Product" p WHERE sp."storeId"=NEW."storeId" AND sp."productId"=coffee_base_ingredient_id AND sp."active"=TRUE AND p."id"=sp."productId" AND p."companyId"=NEW."companyId" AND p."trackStock"=TRUE;
           INSERT INTO "PreparationStockConsumption" ("id","companyId","storeId","saleId","batchId","sourceProductId","ingredientProductId","modifierId","quantity","unit","kind") VALUES (gen_random_uuid()::text,NEW."companyId",NEW."storeId",sale_id,batch_id,prep_item->>'productId',coffee_base_ingredient_id,decaf_modifier_id,consume_qty,'GR',CASE WHEN decaf_modifier_id IS NULL THEN 'RECIPE' ELSE 'MODIFIER_SUBSTITUTION' END) ON CONFLICT DO NOTHING;
         END IF;
         IF extra_modifier_id IS NOT NULL AND coffee_base_ingredient_id IS NOT NULL THEN
           consume_qty:=product_qty*9;
           UPDATE "StoreProduct" sp SET "currentStock"=COALESCE(sp."currentStock",0)-consume_qty FROM "Product" p WHERE sp."storeId"=NEW."storeId" AND sp."productId"=coffee_base_ingredient_id AND sp."active"=TRUE AND p."id"=sp."productId" AND p."companyId"=NEW."companyId" AND p."trackStock"=TRUE;
           INSERT INTO "PreparationStockConsumption" ("id","companyId","storeId","saleId","batchId","sourceProductId","ingredientProductId","modifierId","quantity","unit","kind") VALUES (gen_random_uuid()::text,NEW."companyId",NEW."storeId",sale_id,batch_id,prep_item->>'productId',coffee_base_ingredient_id,extra_modifier_id,consume_qty,'GR','MODIFIER') ON CONFLICT DO NOTHING;
         END IF;
         -- MODIFIER-ONLY MILK: one selected milk, product-specific ML, one stock write.
         IF milk_qty>0 AND milk_target_sku IS NOT NULL THEN
           SELECT p."id" INTO milk_target_ingredient_id FROM "Product" p WHERE p."companyId"=NEW."companyId" AND p."sku"=milk_target_sku AND p."active"=TRUE LIMIT 1;
           IF milk_target_ingredient_id IS NULL THEN RAISE EXCEPTION 'Δεν βρέθηκε ενεργό υλικό για το επιλεγμένο γάλα (%).',milk_target_sku USING ERRCODE='P0001'; END IF;
           consume_qty:=product_qty*milk_qty;
           UPDATE "StoreProduct" sp SET "currentStock"=COALESCE(sp."currentStock",0)-consume_qty FROM "Product" p WHERE sp."storeId"=NEW."storeId" AND sp."productId"=milk_target_ingredient_id AND sp."active"=TRUE AND p."id"=sp."productId" AND p."companyId"=NEW."companyId" AND p."trackStock"=TRUE;
           INSERT INTO "PreparationStockConsumption" ("id","companyId","storeId","saleId","batchId","sourceProductId","ingredientProductId","modifierId","quantity","unit","kind") VALUES (gen_random_uuid()::text,NEW."companyId",NEW."storeId",sale_id,batch_id,prep_item->>'productId',milk_target_ingredient_id,milk_modifier_id,consume_qty,'ML','MODIFIER_MILK') ON CONFLICT DO NOTHING;
         END IF;
         IF ice_target_qty IS NOT NULL AND ice_target_ingredient_id IS NOT NULL AND ice_target_qty>0 THEN
           consume_qty:=product_qty*ice_target_qty;
           UPDATE "StoreProduct" sp SET "currentStock"=COALESCE(sp."currentStock",0)-consume_qty FROM "Product" p WHERE sp."storeId"=NEW."storeId" AND sp."productId"=ice_target_ingredient_id AND sp."active"=TRUE AND p."id"=sp."productId" AND p."companyId"=NEW."companyId" AND p."trackStock"=TRUE;
           INSERT INTO "PreparationStockConsumption" ("id","companyId","storeId","saleId","batchId","sourceProductId","ingredientProductId","modifierId","quantity","unit","kind") VALUES (gen_random_uuid()::text,NEW."companyId",NEW."storeId",sale_id,batch_id,prep_item->>'productId',ice_target_ingredient_id,ice_modifier_id,consume_qty,'GR','MODIFIER_SUBSTITUTION') ON CONFLICT DO NOTHING;
         END IF;

         FOR modifier_json IN SELECT value FROM jsonb_array_elements(COALESCE(prep_item->'modifiers','[]'::jsonb)) LOOP
           IF COALESCE(modifier_json->>'id','') = '' OR COALESCE(modifier_json->>'id','') LIKE 'synthetic-%' THEN CONTINUE; END IF;
           FOR modifier_row IN SELECT c."modifierId",c."ingredientProductId",c."quantity",c."unit",c."multiplierMode",g."description" AS group_name,m."description" AS modifier_name,p."sku" AS ingredient_sku FROM "PreparationModifierConsumption" c JOIN "ManagementModifier" m ON m."id"=c."modifierId" AND m."companyId"=c."companyId" JOIN "ManagementModifierGroup" g ON g."id"=m."groupId" AND g."companyId"=m."companyId" JOIN "Product" p ON p."id"=c."ingredientProductId" AND p."companyId"=c."companyId" WHERE c."companyId"=NEW."companyId" AND c."modifierId"=modifier_json->>'id' LOOP
             IF UPPER(modifier_row.group_name)='ΓΑΛΑ' THEN CONTINUE; END IF;
             IF UPPER(modifier_row.group_name)='ΠΑΓΟΣ' OR modifier_row.ingredient_sku LIKE 'MWS-PREP-MILK-%' THEN CONTINUE; END IF;
             IF UPPER(modifier_row.modifier_name) IN ('DECAF','EXTRA ΔΟΣΗ') THEN CONTINUE; END IF;
             consume_qty := product_qty * modifier_row."quantity";
             UPDATE "StoreProduct" sp SET "currentStock"=COALESCE(sp."currentStock",0)-consume_qty FROM "Product" p WHERE sp."storeId"=NEW."storeId" AND sp."productId"=modifier_row."ingredientProductId" AND sp."active"=TRUE AND p."id"=sp."productId" AND p."companyId"=NEW."companyId" AND p."trackStock"=TRUE;
             INSERT INTO "PreparationStockConsumption" ("id","companyId","storeId","saleId","batchId","sourceProductId","ingredientProductId","modifierId","quantity","unit","kind") VALUES (gen_random_uuid()::text,NEW."companyId",NEW."storeId",sale_id,batch_id,prep_item->>'productId',modifier_row."ingredientProductId",modifier_row."modifierId",consume_qty,modifier_row."unit",'MODIFIER') ON CONFLICT DO NOTHING;
           END LOOP;
         END LOOP;
       END LOOP;

       UPDATE "StorePreparationBatch" SET "status"='CONSUMED',"saleId"=sale_id,"consumedAt"=NOW() WHERE "id"=batch_id AND ("status"='SENT' OR "status"='READY');
     END IF;
   END LOOP;
   RETURN NEW;
 END;
 $function$
CREATE OR REPLACE FUNCTION public.mws_guard_baked_total()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE baked INTEGER; BEGIN SELECT "bakedQuantity" INTO baked FROM "StoreBakedBalance" WHERE "storeId"=NEW."storeId" AND "productId"=NEW."productId" AND "enabled"=TRUE; IF FOUND AND COALESCE(NEW."currentStock",0)<baked THEN RAISE EXCEPTION 'MWS_BAKED_TOTAL_GUARD' USING ERRCODE='23514'; END IF; RETURN NEW; END $function$
CREATE OR REPLACE FUNCTION public.mws_pos_ocr_line_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_company TEXT;
  v_supplier TEXT;
  v_code TEXT;
  v_product TEXT;
BEGIN
  IF UPPER(TRIM(COALESCE(NEW."description",''))) ~ '^ANCHOR[[:space:]]*[0-9]+$'
     OR UPPER(TRIM(COALESCE(NEW."ocrRawText",''))) ~ '^ANCHOR[[:space:]]*[0-9]+$' THEN
    NEW."productId" := NULL;
    NEW."supplierCode" := NULL;
    NEW."detectedBarcode" := NULL;
    NEW."resolutionStatus" := 'INFO';
    NEW."ocrLineType" := 'INFO';
    NEW."quantity" := 0;
    NEW."unitCost" := 0;
    NEW."netAmount" := 0;
    NEW."vatAmount" := 0;
    NEW."grossAmount" := 0;
    RETURN NEW;
  END IF;

  IF COALESCE(TRIM(NEW."supplierCode"),'')='' THEN
    v_code := substring(COALESCE(NEW."ocrRawText",'') from '^\s*([0-9][0-9A-Za-z._/-]{2,39})(?:\s|$)');
    IF v_code IS NOT NULL THEN NEW."supplierCode" := v_code; END IF;
  END IF;

  IF NEW."productId" IS NULL AND COALESCE(TRIM(NEW."supplierCode"),'')<>'' THEN
    SELECT o."companyId",o."supplierId" INTO v_company,v_supplier
    FROM "PurchaseOrder" o WHERE o."id"=NEW."orderId" LIMIT 1;
    IF v_company IS NOT NULL AND v_supplier IS NOT NULL THEN
      SELECT m."productId" INTO v_product
      FROM "SupplierProductMapping" m
      WHERE m."companyId"=v_company AND m."supplierId"=v_supplier
        AND UPPER(REGEXP_REPLACE(TRIM(m."supplierItemCode"),'\s+','','g'))=UPPER(REGEXP_REPLACE(TRIM(NEW."supplierCode"),'\s+','','g'))
      LIMIT 1;
      IF v_product IS NOT NULL THEN
        NEW."productId" := v_product;
        NEW."resolutionStatus" := 'MATCHED';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.mws_preserve_ai_reader_lines()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_new_products JSONB;
  v_new_lines JSONB;
  v_old_lines JSONB;
BEGIN
  IF NEW."resultJson" IS NULL OR OLD."resultJson" IS NULL THEN RETURN NEW; END IF;
  v_new_products:=COALESCE(NEW."resultJson"->'productLines','[]'::jsonb);
  v_new_lines:=COALESCE(NEW."resultJson"->'lines','[]'::jsonb);
  v_old_lines:=COALESCE(OLD."resultJson"->'lines','[]'::jsonb);
  IF jsonb_typeof(v_new_products)='array' AND jsonb_typeof(v_new_lines)='array' AND jsonb_typeof(v_old_lines)='array'
     AND jsonb_array_length(v_new_products)=0 AND jsonb_array_length(v_new_lines)=0 AND jsonb_array_length(v_old_lines)>0 THEN
    NEW."resultJson":=jsonb_set(NEW."resultJson",'{lines}',v_old_lines,true);
    IF COALESCE(jsonb_array_length(COALESCE(NEW."resultJson"->'auditLines','[]'::jsonb)),0)=0 THEN
      NEW."resultJson":=jsonb_set(NEW."resultJson",'{auditLines}',v_old_lines,true);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.mws_preserve_online_transaction_actor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE order_no text; resolved_actor text;
      BEGIN
        order_no := substring(COALESCE(NEW."description",OLD."description",'') from '(KAT-[0-9]+)');
        IF order_no IS NOT NULL THEN
          SELECT a."actorId" INTO resolved_actor
          FROM "StoreOperatorAudit" a
          WHERE a."companyId"=NEW."companyId"
            AND a."storeId"=NEW."storeId"
            AND a."eventType"='ONLINE_SALE_COMPLETED'
            AND a."details"->>'orderNumber'=order_no
          ORDER BY a."createdAt" DESC LIMIT 1;
          IF resolved_actor IS NOT NULL THEN NEW."actorId":=resolved_actor; END IF;
        END IF;
        RETURN NEW;
      END;
      $function$
